.coupon{
	height: 99px;
	background #fff
	overflow hidden
	padding-left: 12px;
	width: 100%;
	.list{
		flex-wrap: nowrap;
	}
	.itemCon{
		background: #E93323;
		border-radius: 8px;
		width:137px;
		height:75px;
		overflow: hidden;
		margin-right: 6px;
	}
	.item{
		flex-shrink 0
		position relative
		display flex
		width:137px;
		height:75px;
		background:rgba(255,255,255,0.9);
		border-radius: 8px;
		color #fff;
		margin-right 10px;
		border:1px solid #E93323;
		.left{
			width 100px
			height 75px
			display flex
			flex-direction column
			align-items center
			justify-content center
			color: #E93323;
			padding-bottom: 5px;
			.num{
				font-size: 22px
				font-weight: 600;

				span {
					font-size: 14px
				}
			}
			.txt{
				font-size: 12px
			}
		}
		.right{
			flex 1
			display flex
			align-items center
			justify-content center
			font-size 12px
			border-left 1px dashed #E93323
			color: #E93323;
			.rightCon{
				width: 21px;
				text-align: center;
				line-height: 1.2;
			}
		}
		.roll{
			position absolute
			width 8px
			height 8px
			border-radius: 0 0 50% 50%
			background: #fff;
			border:1px solid #E93323;
			&.up-roll{
				right: 31px;
				top: -5px;
			}
			&.down-roll{
				right: 31px;
				bottom: -5px;
				border-radius: 50% 50% 0 0;
			}
		}
	}
}
